fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    assert!(!a.is_empty() && !b.is_empty(), "inputs must be non-empty");

    let m = a.len();
    let n = b.len();

    // Compatibility assumption from the problem statement; assert defensively.
    assert!(
        m == n || m == 1 || n == 1,
        "incompatible shapes: lengths are {} and {}",
        m,
        n
    );

    let out_len = m.max(n);

    let out_a: Vec<i8> = if m == out_len {
        a
    } else {
        vec![a[0]; out_len]
    };

    let out_b: Vec<i8> = if n == out_len {
        b
    } else {
        vec![b[0]; out_len]
    };

    (out_a, out_b)
}